// Assuming binfo->num_groups gives the number of groups
    // and binfo->group_size gives the size of each group in bits
    for (int i = 0; i < binfo->num_groups; i++) {
        // Calculate the mask for a full group
        unsigned int mask = (1 << binfo->group_size) - 1;

        // Check if all bits in the current group are set
        if ((bitmap[i] & mask) != mask) {
            // If not all bits are set, return false
            return false;
        }
    }

    // If no groups with unset bits were found, return true
    return true;
